  "test": "from types import SimpleNamespace
import pytest

from langfuse.span_filter import is_known_llm_instrumentor


def test_is_known_llm_instrumentor_huggingface():
    """Ensure the HuggingFace instrumentation scope is recognised as a known LLM instrumentor."""
    span = SimpleNamespace(
        instrumentation_scope=SimpleNamespace(name="opentelemetry.instrumentation.huggingface"),
        attributes=None,
        parent=None,
    )
    assert is_known_llm_instrumentor(span) is True
